head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
scwin.vSPOT_ISU_TRD_MKT_TP_CD = "1";
scwin.vINFO_CONTN_TP_CD = "B";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.getPar, scwin.setPar;
scwin.TR_JOB;
scwin.rowPos;

// var fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID());

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        $c.cm.PanelToGroupBox(panel_Item);

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성
        await scwin.setHeader();
        buttonSet.setInsertStatus();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70036.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert("[종목]를 선택하세요.");
            txb_ISU_CD.focus();
            return;
        } else {
            scwin.initItem();
            scwin.setTitle();
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70036.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_ISU_CD_onclick
 * @description img_ISU_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISU_CD_onclick = function() {
    try {
        scwin.setPar = scwin.setParIsuCd;
        $c.lcd.fn_PopFindDigitalIsuAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70036.img_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_onclick = function() {
    try {
        buttonSet.setInsertStatus();
        scwin.initItem();
        scwin.setTitle();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70036.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_Print_onclick
 * @description 「인쇄」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Print_onclick = async function() {
    try {
        if (scwin.vBzProcsNo === "") {
            await $c.win.alert("목록에서 [대상]를 선택하세요.");
        } else {
            scwin.print();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70036.btn_Print_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70036.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    try {
        scwin.openDetail(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70036.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadError
 * @description dts_Item 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Item_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Item);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70036.dts_Item_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadError
 * @description dts_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Item);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70036.dts_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70036.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt.setValue("총 건수 : " + dts_List.getRowCount());
        // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
        }
        dts_List.setRowPosition(dts_List.getRowCount(), 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70036.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lcd.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70036.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lcd.fn_alertMsg('S');
        await scwin.listSync();
        // fn_initForm("U");
        scwin.initItem();
        if (scwin.TR_JOB === 'U') {
            dts_List.setRowPosition(scwin.rowPos, 0);
            scwin.openDetail(scwin.rowPos);
        } else if (scwin.TR_JOB === 'I') {
            dts_List.setRowPosition(dts_List.getRowCount(), 0);
            scwin.openDetail(dts_List.getRowCount());
        } else if (scwin.TR_JOB === 'D') {
            buttonSet.setInsertStatus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70036.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/digital/Lstproc.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Item.insertRow();
    // alert(dts_Isu.text+" dts_Isu.text");

    const sbmOptions2 = {
        id : "sbm_dts_Isu",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Isu.insertRow();
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    if (trsIdx === '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (trsIdx === '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (trsIdx === '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    dts_Isu.setCellData(1, "ISU_CD", txb_ISU_CD.getValue());
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    // alert("[fn_trs vBzProcsNo] ."+vBzProcsNo);
    dts_Item.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_Item.setCellData(1, "WRT_DD", vCurDate);
    dts_Item.setCellData(1, "INFO_CONTN_TP_CD", scwin.vINFO_CONTN_TP_CD);
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : trsIdx,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     ISUR_CD : scwin.vIsurCd,
    //     COUNT : "2",
    //     LIST_BZ_TP_CD : scwin.VListBzTpCd + ",DIV_IDX[0]=" + "20" + ",DIV_IDX[1]=" + "21"
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/digital/Lstproc.do",
        ref : "dts_Item,dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParIsuCd
 * @description 디지털증권 기타안내
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsuCd = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        scwin.initItem();
        await scwin.listSync();
        scwin.setTitle();
    }
};

/**
 * @method
 * @name setTitle
 * @description 코스콤 전송시 주권, ETF법인은 제목앞에 회사명을 붙이므로 주석처리.
 * @returns {void}
 * @hidden N
 */
scwin.setTitle = function() {
    // 코스콤 전송시 주권, ETF법인은 제목앞에 회사명을 붙이므로 주석처리.
    txb_ADD_INFO_TITLE.setValue(txb_ISU_NM.getValue());
    dts_Isu.setCellData(1, "ISU_CD", txb_ISU_CD.getValue());
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.openDetail = function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO");
    dts_Item.setCellData(1, "BZ_PROCS_NO", dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO"));
    dts_Item.setCellData(1, "MKTACT_NOTI_DD", dts_List.getCellData(dts_List.getRowPosition(), "MKTACT_NOTI_DD"));
    dts_Item.setCellData(1, "INFO_TITLE", dts_List.getCellData(dts_List.getRowPosition(), "INFO_TITLE"));
    dts_Item.setCellData(1, "INFO_CONTN", dts_List.getCellData(dts_List.getRowPosition(), "INFO_CONTN"));
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (vCurDate >= dts_Item.getCellData(1, "MKTACT_NOTI_DD")) {
        buttonSet.setUpdateStatus();
    } else {
        buttonSet.setErrorStatus();
    }
};

/**
 * @method
 * @name initItem
 * @description init Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.initItem = function() {
    dts_Item.Reset();
    dts_Item.insertRow();
    dts_Isu.reset();
    dts_Isu.insertRow();
    scwin.vBzProcsNo = ""; // 초기화

};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if (!$c.stf.checkEmptyValue(txb_ADD_INFO_TITLE, "제목")) return false;
    if (!$c.stf.checkMaxLength(txb_ADD_INFO_TITLE, 200, "제목")) return false;
    if (!$c.stf.checkEmptyValue(txa_INFO_CONTN, "내용")) return false;
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            await scwin.trs(TRS_IDX_INSERT);
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
        scwin.rowPos = dts_List.getRowPosition();
        await scwin.trs(TRS_IDX_UPDATE);
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lcd.fn_check_delete_discls(dts_BzProcsNo, scwin.vBzProcsNo)) return;
    scwin.TR_JOB = 'D';
    if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    await scwin.trs(TRS_IDX_DELETE);
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]를 선택하세요.");
        txb_ISU_CD.focus();
        return;
    }
    if (!await scwin.checkModifyDts()) return false;
    if (scwin.vBzProcsNo === "") {
        await $c.win.alert("[대상]을 선택하세요.");
        return;
    }
    /*
    	if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
    		alert(getMessageParam("MSG-0022", ""));
    		return ;
    	}
     */
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    dts_Isu.setCellData(dts_Isu.getRowPosition(), "ISU_CD", txb_ISU_CD.getValue());
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        // arr[0] = "68372"; //68926(기타안내사항)
        arr[0] = "69576";
        arr[1] = scwin.vBzProcsNo;
        arr[2] = scwin.vIsurCd;
        arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
        arr[4] = txa_INFO_CONTN.text;
        arr[5] = txb_ADD_INFO_TITLE.getValue();
        $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 15;
    const hgt = 785 + 40;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

/**
 * @method
 * @name print
 * @description 화면을 인쇄한다.
 * @returns {void}
 * @hidden N
 */
scwin.print = function() {
    const pdf_rptname = "RLDSTF00004_2";
    let tInfoContn = txa_INFO_CONTN.getValue();
    if (tInfoContn !== '') {
        tInfoContn = $c.ut.replaceAll(tInfoContn, '\n', '<br>');
        tInfoContn = $c.ut.replaceAll(tInfoContn, ' ', '&nbsp;');
    } else {
        tInfoContn = $c.ut.defaultStrHtmlSpace(tInfoContn);
    }
    let userParam = [{
        uid: "ISU_CD",
        unm: $c.ut.defaultStrHtmlSpace(dts_List.getCellData(dts_List.getRowPosition(), "ISU_CD"))
    }, {
        uid: "COM_NM",
        unm: txb_ISU_NM.getValue()
    }, {
        uid: "TITLE",
        unm: txb_INFO_TITLE.getValue() + " (" + txb_ADD_INFO_TITLE.getValue() + ")"
    }, {
        uid: "BODY",
        unm: tInfoContn
    }];
    $c.stf.doLogSave("ULDSTF15660.xml", SCREN_PROCS_TP_CD_05);

    // PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
};

/**
 * @method
 * @name printOld
 * @description 화면을 인쇄한다. (ASIS rexpert-bak 2018-04-03)
 * @returns {void}
 * @hidden N
 */
scwin.printOld = function() {

    // dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    // 껍데기만 만들고 사용자필드를 사용함
    dts_Print.insertRow();
    // dts_Print.NameValue(1, "TEST") = dtsObj.NameValue(1, "COM_NM");
    dts_Print.setCellData(1, "BODY", txa_INFO_CONTN.getValue());

    // 데이타셋
    // var testDateSet = rex_gfGetGauceCsvStrAll(dts_TempPrint, MxDataSet_emp_data );
    const testDateSet = rex_gfGetGauceCsvStr(dts_Print, dts_Print);
    // alert('[testDateSet]'+testDateSet);

    // Rexpert리포트 파일명
    // var rex_rptname = "test/sample4";
    const rex_rptname = "RLDSTF00004";
    let userParam = [{
        uid: "ISUR_CD",
        unm: scwin.vIsurCd
    }, {
        uid: "COM_NM",
        unm: txb_ISU_NM.getValue()
    }, {
        uid: "TITLE",
        unm: txb_INFO_TITLE.getValue() + " (" + txb_ADD_INFO_TITLE.getValue() + ")"
    }];
    $c.stf.doLogSave("ULDSTF15660.xml", SCREN_PROCS_TP_CD_05);
    // Rexpert 미리보기 호출
    $c.rpt.fn_open_report(testDateSet, rex_rptname, userParam);
};

/**
 * @method
 * @name checkModifyDts
 * @description check Modify Dts 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkModifyDts = async function() {
    let rtn = false;
    const a = dts_List.getCellData(dts_List.getRowPosition(), "INFO_TITLE");
    const aa = dts_Item.getCellData(dts_Item.getRowPosition(), "INFO_TITLE");
    const b = dts_List.getCellData(dts_List.getRowPosition(), "INFO_CONTN");
    const bb = dts_Item.getCellData(dts_Item.getRowPosition(), "INFO_CONTN");
    if (a === aa && b === bb) {
        rtn = true;
    } else {
        await $c.win.alert("변경된 내용이 있습니다. [수정] 후 진행하세요.");
        rtn = false;
    }
    return rtn;
};
